export const BUDDY_KB_EXTRA = [
  // ---------------- MATHEMATICS ----------------
  { subject: 'Mathematics', title: 'Indices and Laws of Indices', keywords: ['indices', 'index', 'exponent', 'power law', 'laws of indices'],
    body: `<h4>What indices do</h4><p>An index (plural: indices) tells you how many times to multiply a base by itself: 2^3 = 2 × 2 × 2 = 8.</p><h4>The laws you must know</h4><div class="box">a^m × a^n = a^(m+n) · a^m ÷ a^n = a^(m−n) · (a^m)^n = a^(mn)<br>a^0 = 1 · a^−n = 1/a^n · a^(1/n) = ⁿ√a</div><h4>Worked example</h4><p>Simplify 3^4 × 3^−2 ÷ 3 → 3^(4−2−1) = 3^1 = <b>3</b>.</p><h4>Trap</h4><p>(2 + 3)^2 is 25, NOT 2^2 + 3^2 = 13. Expand brackets first.</p>` },
  { subject: 'Mathematics', title: 'Logarithms', keywords: ['logarithm', 'log base', 'logs', 'antilog'],
    body: `<h4>Definition</h4><p>log_a x = n simply means a^n = x. A logarithm asks: "a raised to what power gives x?"</p><h4>The laws</h4><div class="box">log(xy) = log x + log y · log(x/y) = log x − log y · log(x^n) = n·log x<br>log_a a = 1 · log 1 = 0</div><h4>Worked example</h4><p>log10 1000 = 3 because 10^3 = 1000. And log2 32 = 5 because 2^5 = 32.</p><h4>Trap</h4><p>log(x + y) is NOT log x + log y. The addition law only works for log of a <i>product</i>.</p>` },
  { subject: 'Mathematics', title: 'Set Theory', keywords: ['set theory', 'union', 'intersection', 'venn diagram', 'subset', 'complement'],
    body: `<h4>The symbols</h4><div class="box">A ∪ B = union (everything in A or B) · A ∩ B = intersection (only what is in both)<br>A′ = complement (everything NOT in A) · n(A ∪ B) = n(A) + n(B) − n(A ∩ B)</div><h4>Worked example</h4><p>In a class, 30 play football, 25 play tennis, 12 play both. How many play at least one? n(F ∪ T) = 30 + 25 − 12 = <b>43</b>.</p><h4>Trap</h4><p>In Venn questions, fill the intersection FIRST, then work outwards. "At least one" means the union; "exactly one" excludes the middle.</p>` },
  { subject: 'Mathematics', title: 'Probability', keywords: ['probability', 'chance', 'dice', 'coin toss', 'outcome'],
    body: `<h4>Definition</h4><p>Probability measures how likely an event is: P(event) = favourable outcomes ÷ total outcomes. It always sits between 0 (impossible) and 1 (certain).</p><h4>Key rules</h4><div class="box">P(not A) = 1 − P(A)<br>Independent events together: P(A and B) = P(A) × P(B)<br>Mutually exclusive: P(A or B) = P(A) + P(B)</div><h4>Worked example</h4><p>A fair die is thrown twice. P(two sixes) = 1/6 × 1/6 = <b>1/36</b>. P(at least one six) = 1 − (5/6 × 5/6) = 11/36.</p><h4>Trap</h4><p>"At least one" is fastest as 1 − P(none). Do not add probabilities of independent events.</p>` },
  { subject: 'Mathematics', title: 'Pythagoras Theorem', keywords: ['pythagoras', 'hypotenuse', 'right angled triangle', 'right-angled'],
    body: `<h4>The theorem</h4><p>In a right-angled triangle, the square on the hypotenuse equals the sum of the squares on the other two sides:</p><div class="box">c^2 = a^2 + b^2 (c = hypotenuse, the side opposite the right angle)</div><h4>Worked example</h4><p>Sides 6 cm and 8 cm: c^2 = 36 + 64 = 100, so c = <b>10 cm</b>. Classic triple: 3-4-5 (and 5-12-13, 8-15-17).</p><h4>Converse</h4><p>If c^2 = a^2 + b^2 holds for a triangle's sides, the triangle IS right-angled. If c^2 &lt; a^2 + b^2 it is acute; if c^2 &gt; a^2 + b^2 it is obtuse.</p><h4>Trap</h4><p>Only for right-angled triangles — and c must be the LONGEST side.</p>` },
  { subject: 'Mathematics', title: 'Trigonometric Ratios', keywords: ['trigonometry', 'sine', 'cosine', 'tangent', 'sin cos tan', 'sohcahtoa', 'angle of elevation', 'angle of depression'],
    body: `<h4>SOH CAH TOA</h4><div class="box">sin θ = Opposite/Hypotenuse · cos θ = Adjacent/Hypotenuse · tan θ = Opposite/Adjacent</div><h4>Worked example</h4><p>A ladder 10 m long leans against a wall at 60° to the ground. Height = 10 × sin 60° = 10 × 0.866 = <b>8.66 m</b>.</p><h4>Special values to memorise</h4><p>sin 30° = 0.5, sin 45° = 0.707, sin 60° = 0.866; cos is the same list reversed.</p><h4>Trap</h4><p>Angle of elevation looks UP, angle of depression looks DOWN — they are equal (alternate angles). Label opposite/adjacent relative to the angle given, not to you.</p>` },
  { subject: 'Mathematics', title: 'Sequences and Series', keywords: ['arithmetic progression', 'geometric progression', 'sequence', 'nth term', 'common difference', 'common ratio', 'series'],
    body: `<h4>Arithmetic Progression (AP)</h4><p>Each term adds a common difference d: 3, 7, 11, … (d = 4).</p><div class="box">nth term: Un = a + (n−1)d · Sum: Sn = n/2 [2a + (n−1)d]</div><h4>Geometric Progression (GP)</h4><p>Each term multiplies by a common ratio r: 2, 6, 18, … (r = 3).</p><div class="box">nth term: Un = ar^(n−1) · Sum: Sn = a(r^n − 1)/(r − 1)</div><h4>Worked example</h4><p>Find the 10th term of 5, 9, 13…: U10 = 5 + 9(4) = <b>41</b>.</p><h4>Trap</h4><p>In AP it is (n−1)d, not nd. For GP with r &lt; 1 the sum to infinity is a/(1−r).</p>` },
  { subject: 'Mathematics', title: 'Mensuration', keywords: ['area', 'perimeter', 'volume', 'surface area', 'cylinder', 'cone', 'sphere', 'mensuration'],
    body: `<h4>The formulas that must be automatic</h4><div class="box">Rectangle: A = l × w, P = 2(l + w)<br>Triangle: A = 1/2 × base × height<br>Circle: A = πr^2, C = 2πr<br>Cuboid: V = l × w × h<br>Cylinder: V = πr^2h, curved surface = 2πrh<br>Cone: V = 1/3 πr^2h · Sphere: V = 4/3πr^3, A = 4πr^2</div><h4>Worked example</h4><p>A cylinder with r = 7 cm, h = 10 cm (π = 22/7): V = 22/7 × 49 × 10 = <b>1540 cm^3</b>.</p><h4>Trap</h4><p>Given diameter? Halve it first. Cone and pyramid volumes carry the 1/3 — forgetting it is the most common WAEC loss.</p>` },
  { subject: 'Mathematics', title: 'Statistics — Mean, Median and Mode', keywords: ['mean', 'median', 'mode', 'average', 'statistics', 'frequency table'],
    body: `<h4>The three averages</h4><div class="box">Mean = sum of values ÷ number of values<br>Median = the MIDDLE value when arranged in order<br>Mode = the value that appears MOST often</div><h4>Worked example</h4><p>Scores: 4, 7, 7, 9, 13. Mean = 40/5 = <b>8</b>; median = <b>7</b>; mode = <b>7</b>.</p><h4>From a frequency table</h4><p>Mean = Σfx ÷ Σf — multiply each value by its frequency first.</p><h4>Trap</h4><p>Median needs ORDERED data — with an even count it is the average of the two middle values. An outlier drags the mean but never the mode.</p>` },
  { subject: 'Mathematics', title: 'Ratio, Proportion and Percentages', keywords: ['ratio', 'proportion', 'percentage', 'percent', 'sharing ratio', 'percentage change'],
    body: `<h4>Ratio sharing</h4><p>To share in ratio a:b — add the parts (a + b), divide the quantity by the total parts, then multiply. Share ₦9,000 in 2:3 → parts = 5 → ₦1,800 each → <b>₦3,600 : ₦5,400</b>.</p><h4>Percentage change</h4><div class="box">% change = (change ÷ original) × 100</div><p>A price falls from ₦2,000 to ₦1,700: % decrease = 300/2000 × 100 = <b>15%</b>.</p><h4>Trap</h4><p>Percentage change is always over the ORIGINAL value, never the new one. Reverse percentages: if ₦8,500 is 115%, the original is 8500 ÷ 1.15.</p>` },
  { subject: 'Mathematics', title: 'Number Bases', keywords: ['number base', 'base two', 'binary', 'base 8', 'denary', 'convert base'],
    body: `<h4>To base 10</h4><p>Multiply each digit by its place value: 1101(two) = 1×8 + 1×4 + 0×2 + 1×1 = <b>13</b>.</p><h4>From base 10</h4><p>Divide repeatedly by the new base and read remainders upwards: 25 to base 2 → 25÷2 = 12 r1, 12÷2 = 6 r0, 6÷2 = 3 r0, 3÷2 = 1 r1, 1÷2 = 0 r1 → <b>11001(two)</b>.</p><h4>Trap</h4><p>Read remainders from the LAST one upwards. In any base, the largest single digit is base − 1 (base 8 never contains 8 or 9).</p>` },
  { subject: 'Mathematics', title: 'Variation', keywords: ['direct variation', 'inverse variation', 'joint variation', 'partial variation', 'varies as'],
    body: `<h4>The four types</h4><div class="box">Direct: y = kx · Inverse: y = k/x · Joint: z = kxy · Partial: y = a + bx</div><h4>Worked example</h4><p>y varies directly as x; y = 12 when x = 4 → k = 3, so when x = 9, y = <b>27</b>.</p><h4>Trap</h4><p>Always find k FIRST with the given pair. "Varies as the square" means y = kx^2, "varies inversely as the square root" means y = k/√x.</p>` },
  { subject: 'Mathematics', title: 'Rounding and Significant Figures', keywords: ['significant figures', 'round off', 'decimal places', 'approximation'],
    body: `<h4>The rule</h4><p>Look at the digit AFTER the one you are rounding to: 5 or more rounds UP, less than 5 rounds DOWN.</p><h4>Worked example</h4><p>0.004567 to 2 significant figures = <b>0.0046</b> (leading zeros are NOT significant). 7.845 to 2 decimal places = 7.85.</p><h4>Trap</h4><p>Significant figures start at the first non-zero digit. Keep every zero between non-zero digits.</p>` },

  // ---------------- PHYSICS ----------------
  { subject: 'Physics', title: 'Motion — Speed, Velocity and Acceleration', keywords: ['speed', 'velocity', 'acceleration', 'motion', 'distance time', 'uniform motion'],
    body: `<h4>The definitions</h4><div class="box">Speed = distance/time (scalar) · Velocity = displacement/time (vector)<br>Acceleration = change in velocity/time · SI unit: m/s^2</div><h4>The equations of uniformly accelerated motion</h4><div class="box">v = u + at · s = ut + 1/2 at^2 · v^2 = u^2 + 2as</div><h4>Worked example</h4><p>A car accelerates from rest at 2 m/s^2 for 5 s: v = 0 + 2×5 = <b>10 m/s</b>; distance = 1/2 ×2×25 = 25 m.</p><h4>Trap</h4><p>"From rest" means u = 0. Deceleration is just negative a. Speed is scalar, velocity is vector — WAEC loves that distinction.</p>` },
  { subject: 'Physics', title: "Newton's Laws of Motion", keywords: ['newton law', 'newtons laws', 'inertia', 'law of motion', 'action reaction', 'f = ma'],
    body: `<h4>The three laws</h4><p><b>1st (inertia):</b> a body stays at rest or in uniform motion unless a resultant force acts on it.</p><p><b>2nd:</b> F = ma — force equals mass times acceleration.</p><p><b>3rd:</b> every action has an equal and opposite reaction.</p><h4>Worked example</h4><p>What force gives a 5 kg mass an acceleration of 3 m/s^2? F = 5 × 3 = <b>15 N</b>.</p><h4>Trap</h4><p>Action-reaction pairs act on DIFFERENT bodies — that is why they never cancel. Weight W = mg uses g ≈ 10 m/s^2 in WAEC calculations.</p>` },
  { subject: 'Physics', title: 'Work, Energy and Power', keywords: ['work energy power', 'kinetic energy', 'potential energy', 'power', 'conservation of energy', 'joule'],
    body: `<h4>The formulas</h4><div class="box">Work = force × distance (in the force direction) — unit: joule<br>KE = 1/2 mv^2 · PE = mgh<br>Power = work/time — unit: watt</div><h4>Worked example</h4><p>A 2 kg ball falls from 5 m (g = 10): PE lost = 2×10×5 = 100 J → all becomes KE → 1/2 ×2×v^2 = 100 → v = <b>10 m/s</b>.</p><h4>Trap</h4><p>No movement in the force direction = no work done (carrying a load horizontally does zero work against gravity). Energy is never destroyed, only converted.</p>` },
  { subject: 'Physics', title: 'Simple Machines', keywords: ['simple machine', 'lever', 'pulley', 'mechanical advantage', 'velocity ratio', 'efficiency', 'inclined plane'],
    body: `<h4>The core quantities</h4><div class="box">Mechanical Advantage (MA) = load ÷ effort<br>Velocity Ratio (VR) = distance moved by effort ÷ distance moved by load<br>Efficiency = MA/VR × 100%</div><h4>Worked example</h4><p>A pulley lifts 600 N with 200 N effort, VR = 4: MA = 3, efficiency = 3/4 × 100 = <b>75%</b>.</p><h4>Trap</h4><p>Efficiency is always below 100% because friction wastes some work. A single fixed pulley has VR = 1 — it only changes direction.</p>` },
  { subject: 'Physics', title: 'Waves and Sound', keywords: ['wave', 'wavelength', 'frequency', 'amplitude', 'sound', 'echo', 'transverse', 'longitudinal'],
    body: `<h4>The wave equation</h4><div class="box">v = f × λ (speed = frequency × wavelength)</div><p>Transverse waves vibrate perpendicular to travel (light, ripples); longitudinal waves vibrate parallel (sound).</p><h4>Worked example</h4><p>A sound of frequency 500 Hz has wavelength 0.68 m: v = 500 × 0.68 = <b>340 m/s</b> (the speed of sound in air).</p><h4>Trap</h4><p>Frequency never changes when a wave enters a new medium — speed and wavelength do. Echo problems: the sound travels TWICE the distance.</p>` },
  { subject: 'Physics', title: 'Light — Reflection and Refraction', keywords: ['reflection', 'refraction', 'mirror', 'lens', 'snell', 'total internal reflection', 'critical angle', 'light'],
    body: `<h4>Reflection</h4><p>Angle of incidence = angle of reflection; images in plane mirrors are virtual, upright, same size, laterally inverted.</p><h4>Refraction</h4><div class="box">Snell's law: n = sin i / sin r</div><p>Light bends TOWARDS the normal entering a denser medium. Total internal reflection needs: denser → less dense AND angle above the critical angle (optical fibres, mirages).</p><h4>Trap</h4><p>Angles are always measured from the NORMAL, never from the surface.</p>` },
  { subject: 'Physics', title: 'Electricity — Current, Voltage and Resistance', keywords: ['ohm law', 'ohms law', 'current', 'voltage', 'resistance', 'circuit', 'series parallel', 'electricity'],
    body: `<h4>Ohm's law</h4><div class="box">V = I × R · Power P = VI = I^2R</div><h4>Series vs parallel</h4><div class="box">Series: R total = R1 + R2 + … (same current)<br>Parallel: 1/R = 1/R1 + 1/R2 + … (same voltage)</div><h4>Worked example</h4><p>Two 6 Ω resistors in parallel → 1/R = 1/6 + 1/6 = 1/3 → R = 3 Ω. With 12 V: I = 12/3 = <b>4 A</b>.</p><h4>Trap</h4><p>Two equal resistors in parallel give HALF one resistance. Energy in kWh = (watts × hours)/1000 — that is how NEPA bills work.</p>` },
  { subject: 'Physics', title: 'Magnetism and Electromagnets', keywords: ['magnet', 'magnetic field', 'electromagnet', 'magnetism', 'magnetic materials', 'electromagnetic induction'],
    body: `<h4>The basics</h4><p>Like poles repel, unlike poles attract. Magnetic materials: iron, steel, nickel, cobalt. Field lines run from NORTH to SOUTH outside the magnet.</p><h4>Electromagnets</h4><p>A coil around soft iron becomes magnetic when current flows; strength increases with more turns, more current, and a soft-iron core. Used in bells, relays, scrap cranes.</p><h4>Induction</h4><p>Moving a magnet in/out of a coil INDUCES a voltage — the basis of generators. Faster motion or stronger magnet = bigger voltage.</p><h4>Trap</h4><p>Soft iron loses magnetism quickly (good for electromagnets); steel keeps it (good for permanent magnets).</p>` },
  { subject: 'Physics', title: 'Heat and Temperature', keywords: ['heat', 'temperature', 'conduction', 'convection', 'radiation', 'specific heat', 'thermal expansion'],
    body: `<h4>How heat travels</h4><p><b>Conduction</b> — through solids, particle to particle. <b>Convection</b> — fluids carry heat as currents. <b>Radiation</b> — infrared waves, needs no medium (the Sun).</p><h4>Heat calculations</h4><div class="box">Q = mcθ (mass × specific heat capacity × temperature change)</div><h4>Worked example</h4><p>Heat 2 kg of water (c = 4200 J/kg°C) by 10°C: Q = 2 × 4200 × 10 = <b>84,000 J</b>.</p><h4>Trap</h4><p>Temperature is the degree of hotness (°C or K); heat is ENERGY in transit (joules). Water's high specific heat is why it cools engines.</p>` },
  { subject: 'Physics', title: 'Pressure', keywords: ['pressure', 'pascal', 'atmospheric pressure', 'pressure in fluids', 'barometer'],
    body: `<h4>Definition</h4><div class="box">Pressure = force ÷ area — SI unit: pascal (N/m^2)</div><p>In a liquid: P = ρgh (density × gravity × depth) — pressure grows with depth, not with the shape of the container.</p><h4>Worked example</h4><p>Pressure 10 m under water (ρ = 1000, g = 10): P = 1000 × 10 × 10 = <b>100,000 Pa</b>.</p><h4>Applications</h4><p>Sharp knives cut with small area; wide tyres spread a lorry's weight; syphons, barometers and hydraulic presses all run on pressure principles.</p><h4>Trap</h4><p>Atmospheric pressure at sea level ≈ 760 mmHg ≈ 1.0 × 10^5 Pa — memorise both forms.</p>` },

  // ---------------- CHEMISTRY ----------------
  { subject: 'Chemistry', title: 'Atomic Structure', keywords: ['atom', 'atomic structure', 'proton', 'neutron', 'electron', 'atomic number', 'mass number', 'isotope'],
    body: `<h4>The particles</h4><div class="box">Proton (+1, mass 1) and neutron (0, mass 1) in the nucleus; electron (−1, ~0 mass) in shells.<br>Atomic number Z = protons · Mass number A = protons + neutrons</div><p>Shells fill 2, 8, 8… Valence (outer) electrons decide chemistry.</p><h4>Isotopes</h4><p>Same protons, different neutrons — e.g. chlorine-35 and chlorine-37. Same chemistry, different mass.</p><h4>Worked example</h4><p>An atom has Z = 11, A = 23: 11 protons, 12 neutrons, 11 electrons, configuration 2.8.1 — that is sodium.</p><h4>Trap</h4><p>In a neutral atom, protons = electrons. Ions have lost or gained ELECTRONS only — never protons.</p>` },
  { subject: 'Chemistry', title: 'The Periodic Table', keywords: ['periodic table', 'group', 'period', 'alkali metal', 'halogen', 'noble gas', 'elements arrangement'],
    body: `<h4>How it is organised</h4><p>Elements are arranged by increasing atomic number. <b>Groups</b> (columns) = same valence electrons = similar chemistry. <b>Periods</b> (rows) = same number of shells.</p><h4>The groups to know</h4><div class="box">Group I — alkali metals (Li, Na, K): soft, react violently with water<br>Group VII — halogens (F, Cl, Br): reactive non-metals<br>Group 0 — noble gases: unreactive, full outer shells</div><h4>Trends</h4><p>Across a period: atomic size decreases, metallic character drops. Down a group: reactivity rises for metals, falls for non-metals.</p><h4>Trap</h4><p>Noble gases are inert BECAUSE their outer shells are full — that is the reason behind all bonding.</p>` },
  { subject: 'Chemistry', title: 'Chemical Bonding', keywords: ['bonding', 'ionic bond', 'covalent bond', 'electrovalent', 'metallic bond', 'chemical bond'],
    body: `<h4>The three bonds</h4><p><b>Ionic (electrovalent):</b> metal TRANSFERS electrons to a non-metal — e.g. NaCl. High melting points, conduct when molten/dissolved.</p><p><b>Covalent:</b> non-metals SHARE electrons — e.g. H2O, O2. Low melting points, usually do not conduct.</p><p><b>Metallic:</b> a sea of free electrons around positive ions — conducts, malleable.</p><h4>Worked example</h4><p>Mg (2.8.2) gives 2 electrons to O (2.6) → Mg^2+ and O^2− → ionic MgO.</p><h4>Trap</h4><p>Dative (co-ordinate) covalent = both shared electrons come from ONE atom (e.g. NH4+).</p>` },
  { subject: 'Chemistry', title: 'Acids, Bases and Salts', keywords: ['acid', 'base', 'alkali', 'salt', 'ph scale', 'indicator', 'neutralization', 'neutralisation'],
    body: `<h4>The definitions</h4><p><b>Acids</b> turn blue litmus red, pH below 7 (HCl, H2SO4). <b>Bases</b> turn red litmus blue, pH above 7; soluble bases are alkalis (NaOH).</p><h4>Neutralisation</h4><div class="box">acid + base → salt + water<br>HCl + NaOH → NaCl + H2O</div><p>acid + metal → salt + hydrogen · acid + carbonate → salt + water + CO2</p><h4>Worked example</h4><p>The salt from H2SO4 + KOH is K2SO4 (potassium sulfate) — balance: H2SO4 + 2KOH → K2SO4 + 2H2O.</p><h4>Trap</h4><p>pH 7 = neutral. Salts are named from the acid: HCl → chlorides, H2SO4 → sulfates, HNO3 → nitrates.</p>` },
  { subject: 'Chemistry', title: 'Electrolysis', keywords: ['electrolysis', 'electrolyte', 'electrode', 'anode', 'cathode', 'electroplating', 'faraday'],
    body: `<h4>What happens</h4><p>Electricity decomposes an electrolyte. <b>Anode = positive</b> (attracts anions), <b>cathode = negative</b> (attracts cations). Discharge: ions lose/gain electrons at the electrodes.</p><h4>Classic example</h4><p>Electrolysis of CuSO4 with copper electrodes: copper dissolves at the anode and deposits on the cathode — the basis of electroplating and copper refining.</p><h4>Uses</h4><p>Extracting reactive metals (aluminium from molten cryolite mix), electroplating, purifying copper.</p><h4>Trap</h4><p>At the cathode, the LESS reactive ion discharges (copper beats hydrogen; in NaCl solution hydrogen is produced, not sodium).</p>` },
  { subject: 'Chemistry', title: 'Organic Chemistry — Hydrocarbons', keywords: ['organic chemistry', 'hydrocarbon', 'alkane', 'alkene', 'alkyne', 'crude oil fractions', 'functional group', 'ethanol'],
    body: `<h4>The families</h4><div class="box">Alkanes CnH2n+2 (single bonds, end -ane: methane CH4)<br>Alkenes CnH2n (one double bond, -ene: ethene C2H4)<br>Alkynes CnH2n−2 (one triple bond, -yne: ethyne C2H2)</div><p>Alkanes undergo SUBSTITUTION; alkenes undergo ADDITION (they decolourise bromine water — the test for unsaturation).</p><h4>Crude oil fractions</h4><p>Refinery gas → petrol → kerosene → diesel → lubricating oil → bitumen (order of rising boiling point).</p><h4>Trap</h4><p>Ethanol (C2H5OH) oxidises to ethanoic acid — the alcohol → vinegar family. Combustion of any hydrocarbon gives CO2 + H2O.</p>` },
  { subject: 'Chemistry', title: 'Separation Techniques', keywords: ['separation', 'filtration', 'evaporation', 'distillation', 'chromatography', 'fractional distillation', 'separating funnel', 'mixture separation'],
    body: `<h4>Match the method to the mixture</h4><div class="box">Insoluble solid + liquid → filtration<br>Soluble solid + liquid → evaporation/crystallisation<br>Miscible liquids with close boiling points → fractional distillation (crude oil, ethanol-water)<br>Immiscible liquids → separating funnel (oil + water)<br>Dyes/pigments → chromatography<br>Solid mixtures by solubility → crystallisation; iron from sand → magnet</div><h4>Worked example</h4><p>To get pure water from muddy salty water: filter the mud, then distil the salt water.</p><h4>Trap</h4><p>Simple distillation separates liquids with FAR-apart boiling points; fractional distillation handles close ones via the fractionating column.</p>` },
  { subject: 'Chemistry', title: 'Metals and Non-metals', keywords: ['metal', 'non metal', 'reactivity series', 'metal properties', 'extraction of metals', 'rusting', 'alloy'],
    body: `<h4>Contrast them</h4><p>Metals: shiny, malleable, ductile, conduct heat and electricity, form basic oxides. Non-metals: dull, brittle, poor conductors, form acidic oxides.</p><h4>Reactivity series (memorise)</h4><div class="box">K Na Ca Mg Al Zn Fe Pb (H) Cu Hg Ag Au — "Please Send Charlie's Monkeys And Zebras Into Leo's Purple Hutage Copper Hut…"</div><p>A more reactive metal displaces a less reactive one from its salt: Zn + CuSO4 → ZnSO4 + Cu.</p><h4>Rusting</h4><p>Iron rusts with BOTH air and water; prevention = paint, oil, galvanising (zinc coat).</p><h4>Trap</h4><p>Extraction method depends on reactivity: electrolysis for K–Al, reduction with carbon for Zn–Pb, heating alone for Cu and below.</p>` },
  { subject: 'Chemistry', title: 'The Gas Laws', keywords: ['boyle law', 'charles law', 'gas law', 'general gas equation', 'pressure volume', 'ideal gas'],
    body: `<h4>The laws</h4><div class="box">Boyle: P1V1 = P2V2 (constant temperature)<br>Charles: V1/T1 = V2/T2 (constant pressure — T in KELVIN)<br>General: P1V1/T1 = P2V2/T2</div><h4>Worked example</h4><p>A gas occupies 400 cm^3 at 1 atm. Compressed to 2 atm at the same temperature: V = 400×1/2 = <b>200 cm^3</b>.</p><h4>Trap</h4><p>ALWAYS convert °C to kelvin (K = °C + 273). STP = 0°C and 760 mmHg; molar volume at STP = 22.4 dm^3.</p>` },

  // ---------------- BIOLOGY ----------------
  { subject: 'Biology', title: 'The Cell', keywords: ['cell', 'cell membrane', 'nucleus', 'cytoplasm', 'mitochondria', 'plant cell', 'animal cell', 'organelle'],
    body: `<h4>The living unit</h4><p>The cell is the basic structural and functional unit of all living things.</p><h4>Key organelles</h4><div class="box">Nucleus — controls the cell, holds DNA<br>Mitochondrion — respiration, releases energy ("powerhouse")<br>Cell membrane — controls what enters/leaves<br>Cytoplasm — site of chemical reactions</div><p><b>Plant cells only:</b> cell wall (cellulose, support), chloroplasts (photosynthesis), large permanent vacuole.</p><h4>Worked example</h4><p>A muscle cell has many mitochondria because it needs constant energy; red blood cells have NO nucleus to carry more haemoglobin.</p><h4>Trap</h4><p>"Which organelle is in plant but not animal cells?" — cell wall, chloroplast AND large vacuole; name all three when asked.</p>` },
  { subject: 'Biology', title: 'Photosynthesis', keywords: ['photosynthesis', 'chlorophyll', 'chloroplast', 'light energy', 'carbon dioxide water glucose'],
    body: `<h4>The definition</h4><p>Photosynthesis is the process by which green plants manufacture glucose from carbon dioxide and water, using light energy trapped by chlorophyll.</p><div class="box">6CO2 + 6H2O --(light + chlorophyll)--&gt; C6H12O6 + 6O2</div><h4>Two stages</h4><p><b>Light stage:</b> water splits (photolysis), oxygen released, energy captured. <b>Dark stage:</b> CO2 is fixed into glucose — no light needed directly.</p><h4>Factors that affect the rate</h4><p>Light intensity, CO2 concentration, temperature, water and chlorophyll.</p><h4>Worked example</h4><p>Test a leaf for starch: boil, remove chlorophyll with alcohol, add iodine — blue-black = starch present = photosynthesis happened.</p><h4>Trap</h4><p>Photosynthesis BALANCES respiration in nature: it takes in CO2 and releases O2 — the reverse gas exchange of respiration.</p>` },
  { subject: 'Biology', title: 'Respiration', keywords: ['respiration', 'aerobic', 'anaerobic', 'cellular respiration', 'atp', 'fermentation'],
    body: `<h4>The definition</h4><p>Respiration is the breakdown of food (glucose) in cells to release energy (ATP).</p><h4>Aerobic vs anaerobic</h4><div class="box">Aerobic: C6H12O6 + 6O2 → 6CO2 + 6H2O + energy (38 ATP) — plenty of energy<br>Anaerobic (animals): glucose → lactic acid + little energy (muscle cramps)<br>Anaerobic (yeast): glucose → ethanol + CO2 + little energy (fermentation)</div><h4>Worked example</h4><p>During hard exercise your muscles respire anaerobically — lactic acid builds up, causing cramp; rest and oxygen repay the "oxygen debt".</p><h4>Trap</h4><p>Breathing is NOT respiration — breathing is gas exchange; respiration is the CHEMICAL release of energy inside cells.</p>` },
  { subject: 'Biology', title: 'The Digestive System', keywords: ['digestion', 'digestive system', 'enzymes', 'small intestine', 'stomach acid', 'villi', 'peristalsis'],
    body: `<h4>The journey</h4><p>Mouth → oesophagus → stomach → small intestine → large intestine → rectum.</p><h4>Enzymes to memorise</h4><div class="box">Mouth: salivary amylase (starch → maltose)<br>Stomach: pepsin + HCl (proteins → peptides)<br>Small intestine: trypsin (proteins), lipase (fats), maltase (maltose → glucose)</div><p>Bile (from the liver) EMULSIFIES fats — it is not an enzyme.</p><h4>Absorption</h4><p>Villi in the small intestine give a huge surface area; glucose and amino acids enter blood, fatty acids enter lacteals.</p><h4>Trap</h4><p>Peristalsis = wave-like muscular movement pushing food along. Digestion ends in the small intestine — the large intestine only absorbs water and salts.</p>` },
  { subject: 'Biology', title: 'Transport Systems — Blood and Circulation', keywords: ['blood', 'circulation', 'heart', 'artery', 'vein', 'capillary', 'haemoglobin', 'transport system'],
    body: `<h4>The blood components</h4><div class="box">Red cells — carry O2 with haemoglobin (no nucleus)<br>White cells — defend against disease<br>Platelets — clotting<br>Plasma — liquid carrying dissolved food, wastes, hormones</div><h4>Vessels</h4><p>Arteries: thick walls, carry blood AWAY from the heart (usually oxygenated — except pulmonary artery). Veins: valves, carry blood TO the heart. Capillaries: one-cell thick for exchange.</p><h4>Double circulation</h4><p>Heart → lungs → heart → body → heart. The left side pumps oxygenated blood; the right pumps deoxygenated.</p><h4>Trap</h4><p>The pulmonary artery is the ONLY artery carrying deoxygenated blood — examiners' favourite trick.</p>` },
  { subject: 'Biology', title: 'Ecology', keywords: ['ecology', 'ecosystem', 'food chain', 'food web', 'habitat', 'population', 'community', 'decomposer', 'trophic'],
    body: `<h4>The terms</h4><div class="box">Habitat — where an organism lives · Population — same species in an area<br>Community — all populations together · Ecosystem — community + non-living factors</div><h4>Feeding relationships</h4><p>Food chain: grass → grasshopper → lizard → hawk (producer → primary → secondary → tertiary consumer). Decomposers (bacteria, fungi) recycle dead matter.</p><h4>Energy flow</h4><p>Only about 10% of energy passes to the next trophic level — that is why food chains rarely exceed four links.</p><h4>Worked example</h4><p>In "maize → rat → snake → eagle", removing all snakes makes rats explode and eagles decline — every link matters.</p><h4>Trap</h4><p>The food chain ALWAYS starts with a green plant (producer). Pyramid of energy is always upright.</p>` },
  { subject: 'Biology', title: 'Reproduction in Plants and Animals', keywords: ['reproduction', 'pollination', 'fertilisation', 'gamete', 'ovary', 'testes', 'menstrual', 'sexual asexual'],
    body: `<h4>Two kinds</h4><p><b>Asexual:</b> one parent, identical offspring (binary fission, budding, vegetative propagation). <b>Sexual:</b> two gametes fuse — variation.</p><h4>In flowering plants</h4><p>Pollination = transfer of pollen from anther to stigma (self or cross). Fertilisation = male nucleus fuses with ovule → seed; ovary becomes fruit.</p><h4>In humans</h4><p>Testes produce sperm; ovaries release one egg monthly (ovulation). Fertilisation happens in the OVIDUCT (fallopian tube); the embryo implants in the uterus wall.</p><h4>Trap</h4><p>Pollination and fertilisation are DIFFERENT events — pollination must come first. Cross-pollination gives variation; self-pollination keeps traits uniform.</p>` },
  { subject: 'Biology', title: 'Excretion', keywords: ['excretion', 'kidney', 'nephron', 'urine', 'skin excretion', 'liver', 'osmoregulation', 'homeostasis'],
    body: `<h4>Definition</h4><p>Excretion is the removal of metabolic waste from the body — NOT undigested food (that is egestion/faeces).</p><h4>The organs</h4><div class="box">Kidneys — urea, excess water and salts (urine)<br>Skin — sweat (water, salts, trace urea)<br>Lungs — carbon dioxide and water vapour<br>Liver — converts toxic ammonia to urea, breaks down old red cells</div><h4>The kidney unit</h4><p>The nephron filters blood (ultrafiltration), then reabsorbs all glucose, most water and needed salts — selective reabsorption.</p><h4>Trap</h4><p>Glucose in urine signals diabetes. Urea is MADE in the liver but REMOVED by the kidneys — do not mix them up.</p>` },
  { subject: 'Biology', title: 'The Nervous System', keywords: ['nervous system', 'neuron', 'nerve', 'reflex action', 'brain', 'spinal cord', 'central nervous system', 'synapse'],
    body: `<h4>Organisation</h4><p>CNS = brain + spinal cord; PNS = nerves. The neurone carries impulses: dendron → cell body → axon; the gap between neurones is a synapse.</p><h4>Reflex arc</h4><div class="box">Receptor → sensory neurone → spinal cord (relay) → motor neurone → effector</div><p>Reflexes are rapid, automatic, involuntary — they protect the body (jerking from a hot pot happens BEFORE you feel pain).</p><h4>Brain parts</h4><p>Cerebrum — thinking, memory; cerebellum — balance and coordination; medulla — heartbeat, breathing (vital centres).</p><h4>Trap</h4><p>Voluntary actions start in the cerebrum; reflexes bypass the brain entirely via the spinal cord.</p>` },

  // ---------------- ENGLISH LANGUAGE ----------------
  { subject: 'English Language', title: 'Tenses', keywords: ['tenses', 'present tense', 'past tense', 'future tense', 'perfect tense', 'continuous tense'],
    body: `<h4>The twelve at a glance</h4><div class="box">Simple: I write / I wrote / I will write<br>Continuous: I am writing / I was writing / I will be writing<br>Perfect: I have written / I had written / I will have written<br>Perfect continuous: I have been writing…</div><h4>The signals</h4><p>"Yesterday, last week, ago" → past. "Since, for, already, just" → perfect. "Now, at the moment" → continuous. "Tomorrow, next year" → future.</p><h4>Worked example</h4><p>"She ____ (go) to school before I woke." → She <b>had gone</b> — past perfect for the earlier of two past actions.</p><h4>Trap</h4><p>"Have" pairs with past PARTICIPLE (written, gone, eaten), never past simple (wrote, went). Stative verbs (know, belong) rarely take -ing.</p>` },
  { subject: 'English Language', title: 'Subject-Verb Agreement (Concord)', keywords: ['concord', 'subject verb agreement', 'agreement', 'singular plural verb', 'either or neither'],
    body: `<h4>The golden rule</h4><p>A singular subject takes a singular verb; plural takes plural: "The boy <b>runs</b>. The boys <b>run</b>."</p><h4>The tricky cases</h4><div class="box">Either/neither…or/nor → verb agrees with the NEARER subject: "Either the boys or the man <b>is</b> guilty."<br>Everyone, each, nobody → SINGULAR: "Everyone <b>has</b> a book."<br>Collective nouns → singular when acting as one: "The team <b>is</b> winning."<br>Bread and butter (one idea) → singular</div><h4>Worked example</h4><p>"Neither of the answers ____ correct." → <b>is</b> (neither = singular).</p><h4>Trap</h4><p>Ignore words between subject and verb: "The box of chocolates <b>is</b> here" — the subject is box, not chocolates.</p>` },
  { subject: 'English Language', title: 'Active and Passive Voice', keywords: ['active voice', 'passive voice', 'voice', 'by the', 'change the voice'],
    body: `<h4>The swap</h4><p>Active: subject DOES the action. Passive: subject RECEIVES it.</p><div class="box">Active: The cat ate the fish.<br>Passive: The fish was eaten by the cat.</div><h4>The formula</h4><p>Object becomes subject + the right form of "be" + past participle (+ by agent). Tense lives in the "be": is eaten / was eaten / has been eaten / will be eaten.</p><h4>Worked example</h4><p>"Someone stole my pen" → "My pen <b>was stolen</b> (by someone)." Questions: "Who wrote this?" → "By whom was this written?"</p><h4>Trap</h4><p>Never lose the tense. Intransitive verbs (sleep, arrive) have NO passive form.</p>` },
  { subject: 'English Language', title: 'Comprehension Strategy', keywords: ['comprehension', 'passage', 'comprehension strategy', 'reading passage', 'comprehension questions'],
    body: `<h4>The winning method</h4><p><b>1.</b> Read the QUESTIONS first — then you hunt with purpose. <b>2.</b> Skim the passage for the gist. <b>3.</b> Scan for keywords from each question. <b>4.</b> Answer in your OWN words unless asked to quote.</p><h4>Question types</h4><div class="box">"According to the passage…" → answer is IN the text — find it<br>"The writer implies…" → read between the lines<br>"What does 'it' refer to?" → look at the sentence BEFORE<br>"Replace the word…" → the substitute must fit grammar AND meaning</div><h4>Trap</h4><p>Never use outside knowledge — comprehension marks come from the passage alone. Quote exactly when told to quote.</p>` },
  { subject: 'English Language', title: 'Essay and Letter Formats', keywords: ['essay format', 'letter format', 'formal letter', 'informal letter', 'article writing', 'speech writing', 'composition'],
    body: `<h4>Formal letter</h4><div class="box">Two addresses (yours top-right with date; theirs left, below)<br>"Dear Sir/Madam," → title of purpose → 3+ paragraphs → "Yours faithfully," → full name</div><h4>Informal letter</h4><p>One address, "Dear Chidi,", warm tone, "Yours sincerely," + first name.</p><h4>Article/speech</h4><p>Heading, greeting ("Good morning, fellow students"), body, closing thanks.</p><h4>Essay structure</h4><p>Introduction (state your position) → 3 body paragraphs (point, evidence, explanation) → conclusion.</p><h4>Trap</h4><p>Formal = "Yours faithfully"; informal = "Yours sincerely". Mixing them loses a format mark instantly.</p>` },
  { subject: 'English Language', title: 'Reported (Indirect) Speech', keywords: ['direct speech', 'indirect speech', 'reported speech', 'say said tell told'],
    body: `<h4>The backshift rule</h4><p>When reporting, tenses move one step back and pronouns shift:</p><div class="box">"I am tired," he said → He said (that) he <b>was</b> tired.<br>"I will come" → He said he <b>would</b> come.<br>"Do not go" → He told me <b>not to go</b>.</div><h4>Questions</h4><p>Wh- questions keep the question word but lose the question order: "Where are you?" → He asked where I <b>was</b>. Yes/no questions use if/whether.</p><h4>Trap</h4><p>"Say" takes no object ("He said that…"); "tell" needs one ("He told ME"). Time words shift too: today → that day, tomorrow → the next day.</p>` },

  // ---------------- LITERATURE ----------------
  { subject: 'Literature-in-English', title: 'Literary Devices', keywords: ['literary device', 'simile', 'metaphor', 'personification', 'irony', 'symbolism', 'alliteration', 'hyperbole', 'imagery'],
    body: `<h4>The toolkit</h4><div class="box">Simile — comparison with "like/as": brave <i>like</i> a lion<br>Metaphor — direct comparison: he <i>is</i> a lion<br>Personification — human qualities to objects: the wind <i>whispered</i><br>Hyperbole — exaggeration: I have told you a <i>million</i> times<br>Irony — words/events mean the opposite<br>Alliteration — repeated initial sounds: sweet silent sleep</div><h4>How to answer</h4><p>Name the device → quote the exact line → explain its EFFECT (what feeling or picture it creates). Never just identify — the mark is in the effect.</p><h4>Trap</h4><p>"As brave as a lion" is simile; "a lion of a man" is metaphor. Symbolism = an object standing for an idea (a chain = oppression).</p>` },
  { subject: 'Literature-in-English', title: 'Drama and Prose Terms', keywords: ['drama', 'prose', 'protagonist', 'antagonist', 'tragedy', 'comedy', 'plot', 'setting', 'theme', 'flashback', 'climax'],
    body: `<h4>Core terms</h4><div class="box">Protagonist — the main character · Antagonist — the opposing force<br>Plot — sequence of events (exposition → rising action → climax → resolution)<br>Setting — time and place · Theme — the central idea<br>Tragedy — ends in downfall · Comedy — ends happily<br>Flashback — an earlier scene inserted later</div><h4>Drama specifics</h4><p>Plays are MEANT to be performed: dialogue, stage directions, acts and scenes. Soliloquy = a character speaking their thoughts alone.</p><h4>Trap</h4><p>Theme is an IDEA in a sentence ("the danger of unchecked ambition"), not one word ("ambition"). Support every claim with evidence from the text.</p>` },
  { subject: 'Literature-in-English', title: 'Things Fall Apart — Chinua Achebe', keywords: ['things fall apart', 'achebe', 'okonkwo', 'unofia', 'igbo culture', 'colonialism in literature'],
    body: `<h4>The story in brief</h4><p>Okonkwo, a proud yam farmer of Umuofia, fears weakness (his father Unoka was gentle and poor). Exiled for a accidental killing, he returns to find missionaries and colonial rule dissolving Igbo society. Unable to bend, he hangs himself.</p><h4>Key themes</h4><p>Tradition vs change, masculinity and its dangers, fate (chi), the collapse of a society from within and without.</p><h4>Symbols</h4><p>Yams = wealth and masculinity; fire = Okonkwo's temper ("Roaring Flame"); locusts = the arriving colonists.</p><h4>Trap</h4><p>Okonkwo is a TRAGIC hero — his greatness and his flaw are the same thing: inflexible pride. Quote the proverbs; Achebe built the novel on them.</p>` },

  // ---------------- ECONOMICS ----------------
  { subject: 'Economics', title: 'Demand and Supply', keywords: ['demand', 'supply', 'equilibrium price', 'demand curve', 'supply curve', 'market equilibrium', 'shortage surplus'],
    body: `<h4>The laws</h4><p><b>Demand:</b> the higher the price, the lower the quantity demanded (curve slopes down). <b>Supply:</b> the higher the price, the higher the quantity supplied (curve slopes up).</p><h4>Equilibrium</h4><p>Where the curves cross: quantity demanded = quantity supplied. Above it → surplus; below it → shortage.</p><h4>Shifts vs movements</h4><div class="box">Price change → MOVEMENT along the curve<br>Income, taste, population, weather, subsidies → SHIFT of the curve</div><h4>Worked example</h4><p>A drought shifts the maize supply curve LEFT → equilibrium price rises, quantity falls.</p><h4>Trap</h4><p>"Change in demand" (shift) and "change in quantity demanded" (movement) are different marks — name the right one.</p>` },
  { subject: 'Economics', title: 'Elasticity of Demand', keywords: ['elasticity', 'elastic demand', 'inelastic', 'price elasticity', 'ped'],
    body: `<h4>The idea</h4><p>Elasticity measures how strongly quantity reacts to a price change.</p><div class="box">PED = % change in quantity demanded ÷ % change in price<br>PED &gt; 1 elastic (luxuries, many substitutes) · PED &lt; 1 inelastic (necessities: salt, medicine)</div><h4>Why firms care</h4><p>Elastic good → a price CUT raises total revenue. Inelastic good → a price RISE raises total revenue. Governments tax inelastic goods heavily — people keep buying.</p><h4>Worked example</h4><p>Price up 10%, quantity falls 25%: PED = 25/10 = 2.5 → elastic.</p><h4>Trap</h4><p>PED is normally written without the minus sign. Perfectly inelastic demand = vertical line (life-saving drug).</p>` },
  { subject: 'Economics', title: 'Market Structures', keywords: ['market structure', 'perfect competition', 'monopoly', 'oligopoly', 'monopolistic competition'],
    body: `<h4>The four structures</h4><div class="box">Perfect competition — many sellers, identical products, price takers (agricultural markets)<br>Monopolistic competition — many sellers, differentiated products (restaurants, soaps)<br>Oligopoly — few large sellers, interdependent (banks, cement, telecoms)<br>Monopoly — one seller, no close substitute (historically: NEPA, railways)</div><h4>Monopoly causes</h4><p>Legal licence, control of a resource, huge capital needs, patents.</p><h4>Trap</h4><p>Only perfect competition has PRICE = marginal cost efficiency. Oligopolies compete on advertising, not just price.</p>` },
  { subject: 'Economics', title: 'Money and Inflation', keywords: ['money', 'inflation', 'deflation', 'functions of money', 'central bank', 'monetary policy', 'purchasing power'],
    body: `<h4>Functions of money</h4><p>Medium of exchange, unit of account, store of value, standard for deferred payment.</p><h4>Inflation</h4><p>A general, sustained rise in prices — money buys less. Causes: too much money chasing too few goods (demand-pull), rising production costs (cost-push).</p><div class="box">Inflation rate = (new CPI − old CPI)/old CPI × 100</div><p>The CBN fights it by raising interest rates and selling securities (contractionary policy).</p><h4>Worked example</h4><p>CPI rises from 200 to 230: inflation = 30/200 × 100 = <b>15%</b>.</p><h4>Trap</h4><p>Inflation HURTS people on fixed incomes (pensioners) but can HELP debtors — they repay in cheaper money.</p>` },
  { subject: 'Economics', title: 'Government Budget and Fiscal Policy', keywords: ['budget', 'fiscal policy', 'budget deficit', 'budget surplus', 'taxation', 'government revenue', 'national debt'],
    body: `<h4>Budget types</h4><div class="box">Balanced — revenue = expenditure<br>Surplus — revenue &gt; expenditure (used to cool inflation)<br>Deficit — expenditure &gt; revenue → borrowing/national debt (used to fight recession and fund development)</div><h4>Fiscal policy tools</h4><p>Taxation and government spending. Higher taxes + lower spending slows an overheating economy; lower taxes + higher spending stimulates it.</p><h4>Tax types</h4><p>Direct (income tax, company tax) and indirect (VAT, customs duties). Progressive tax takes a larger % from the rich.</p><h4>Trap</h4><p>Fiscal policy = government (taxes/spending); monetary policy = central bank (interest rates/money supply). Never swap them in an exam.</p>` },
  { subject: 'Economics', title: 'Factors of Production', keywords: ['factors of production', 'land labour capital', 'entrepreneur', 'reward for capital', 'division of labour'],
    body: `<h4>The four factors and their rewards</h4><div class="box">Land → rent · Labour → wages<br>Capital → interest · Entrepreneur → profit</div><p>Capital here means man-made aids to production (machinery, tools, buildings) — not just money.</p><h4>Division of labour</h4><p>Breaking production into small repeated tasks: higher output and skill, but monotony and risk of unemployment from machines.</p><h4>Worked example</h4><p>In a bakery: the oven is capital, the baker is labour, the shop is land, and the owner who bears the risk is the entrepreneur.</p><h4>Trap</h4><p>The entrepreneur's reward is PROFIT and their role is organising + risk-bearing — that combination is what examiners want.</p>` },

  // ---------------- COMMERCE ----------------
  { subject: 'Commerce', title: 'Commerce and Trade', keywords: ['commerce', 'trade', 'aids to trade', 'home trade', 'foreign trade', 'entrepot', 'commerce definition'],
    body: `<h4>The chain</h4><p>Production → distribution → consumption. <b>Trade</b> = buying and selling. <b>Commerce</b> = trade PLUS the aids to trade.</p><h4>The aids to trade (memorise all)</h4><div class="box">Banking (finance) · Insurance (risk) · Transportation (movement)<br>Warehousing (storage) · Advertising (information) · Communication · Tourism</div><h4>Trade types</h4><p>Home trade: wholesale and retail. Foreign trade: imports, exports and entrepot (importing to re-export).</p><h4>Trap</h4><p>Commerce does NOT include production itself — it starts after the goods exist.</p>` },
  { subject: 'Commerce', title: 'The Marketing Mix (4 Ps)', keywords: ['marketing mix', '4ps', 'product price place promotion', 'marketing'],
    body: `<h4>The four Ps</h4><div class="box">Product — what you sell: quality, design, packaging, brand<br>Price — what it costs: penetration (low to enter) vs skimming (high at launch)<br>Place — distribution: how it reaches the customer (channels, retailing)<br>Promotion — telling people: advertising, sales promotion, personal selling, publicity</div><h4>Worked example</h4><p>A new gala: tasty recipe (product), ₦200 price (price), sold at bus stops everywhere (place), radio jingles (promotion).</p><h4>Trap</h4><p>Advertising is PAID, identified promotion; publicity is FREE media coverage. Exam questions love that distinction.</p>` },
  { subject: 'Commerce', title: 'Insurance', keywords: ['insurance', 'premium', 'indemnity', 'utmost good faith', 'subrogation', 'life assurance', 'insurance principles'],
    body: `<h4>The idea</h4><p>Insurance spreads risk: many pay small premiums so the few who suffer losses are compensated.</p><h4>Principles</h4><div class="box">Utmost good faith — disclose everything material<br>Indemnity — restored to your previous position, no profit from loss (not for life assurance)<br>Insurable interest — you must stand to lose<br>Subrogation — after paying, the insurer owns your claim against the guilty party<br>Contribution — several insurers share the loss</div><h4>Worked example</h4><p>Your insured car (₦2m) is destroyed — the insurer pays ₦2m, not more, and may sue the careless driver itself (subrogation).</p><h4>Trap</h4><p>Life assurance pays a fixed sum (a life has no price) — the principle of indemnity does NOT apply to it.</p>` },
  { subject: 'Commerce', title: 'Forms of Business Organisation', keywords: ['sole proprietor', 'partnership', 'limited liability', 'company', 'cooperative', 'business organisation', 'joint stock'],
    body: `<h4>The ladder</h4><div class="box">Sole proprietor — one owner: easy to start, unlimited liability<br>Partnership — 2–20 owners: deed of partnership, usually unlimited liability<br>Limited liability company — shareholders' liability limited to their shares; private (Ltd) cannot sell shares publicly, public (Plc) can<br>Cooperatives — members with equal voting rights<br>Public corporations — government-owned services</div><h4>Worked example</h4><p>Dangote Cement Plc can raise billions on the stock exchange; a one-man kiosk cannot — that is limited liability at work.</p><h4>Trap</h4><p>Unlimited liability means business debts can consume the owner's PERSONAL property — the sole trader's greatest weakness.</p>` },
  { subject: 'Commerce', title: 'Banking', keywords: ['bank', 'commercial bank', 'central bank', 'types of bank', 'cheque', 'banking services'],
    body: `<h4>Commercial banks</h4><p>Take deposits, give loans, run current/savings accounts — they create credit. Profit from the interest spread.</p><h4>The Central Bank (CBN)</h4><p>Banker to government and other banks, issues currency, controls monetary policy, lender of last resort — it does NOT deal with ordinary customers.</p><h4>Instruments</h4><div class="box">Cheque — order to a bank to pay; crossed cheques must go through an account<br>Standing order — automatic repeated payments · Direct debit — merchant pulls money with your consent</div><h4>Trap</h4><p>A crossed cheque can only be PAID INTO an account, never cashed over the counter — a favourite trick question.</p>` },

  // ---------------- FINANCIAL ACCOUNTING ----------------
  { subject: 'Financial Accounting', title: 'Double Entry Bookkeeping', keywords: ['double entry', 'debit', 'credit', 'journal', 'ledger', 'bookkeeping'],
    body: `<h4>The rule</h4><div class="box">Every transaction has a debit AND an equal credit.<br>Debit what comes IN / expenses / assets · Credit what goes OUT / income / liabilities</div><h4>Worked example</h4><p>Bought goods ₦5,000 cash → Debit Purchases ₦5,000; Credit Cash ₦5,000. Sold on credit to Ada ₦8,000 → Debit Ada (debtor); Credit Sales.</p><h4>The flow</h4><p>Journal → ledger accounts → trial balance → final accounts.</p><h4>Trap</h4><p>"Cash paid for rent" debits RENT (expense), not cash — beginners debit the wrong side of the pair.</p>` },
  { subject: 'Financial Accounting', title: 'Trial Balance and Final Accounts', keywords: ['trial balance', 'final accounts', 'trading account', 'profit and loss account', 'balance sheet', 'statement of financial position', 'gross profit'],
    body: `<h4>The order</h4><div class="box">Trial balance: lists all ledger balances — total debits MUST equal total credits<br>Trading account: Sales − Cost of sales = GROSS profit<br>Profit &amp; loss: Gross profit − expenses = NET profit<br>Balance sheet: Assets = Capital + Liabilities</div><h4>Cost of sales formula</h4><div class="box">Opening stock + Purchases + Carriage in − Closing stock</div><h4>Worked example</h4><p>Opening 2,000 + purchases 10,000 + carriage 500 − closing 3,000 = cost of sales 9,500. Sales 15,000 → gross profit 5,500.</p><h4>Trap</h4><p>Carriage IN is part of cost of sales; carriage OUT is an expense below gross profit. A trial balance that agrees proves arithmetic — not that entries went to the RIGHT accounts.</p>` },
  { subject: 'Financial Accounting', title: 'Depreciation', keywords: ['depreciation', 'straight line', 'reducing balance', 'accumulated depreciation', 'asset life'],
    body: `<h4>Why assets depreciate</h4><p>Wear and tear, usage, obsolescence and the passage of time reduce an asset's value. Depreciation spreads the cost over its useful life (matching principle).</p><h4>The methods</h4><div class="box">Straight line: (Cost − Residual value) ÷ Useful life — same charge every year<br>Reducing balance: fixed % of the book value each year — bigger early charges</div><h4>Worked example</h4><p>Machine ₦100,000, residual ₦10,000, life 5 years: straight-line charge = 90,000/5 = ₦18,000 per year.</p><h4>Trap</h4><p>Depreciation is a NON-CASH expense — no money leaves the business. Land is never depreciated.</p>` },
  { subject: 'Financial Accounting', title: 'Source Documents', keywords: ['source document', 'invoice', 'receipt', 'credit note', 'debit note', 'voucher', 'statement of account'],
    body: `<h4>The paper trail</h4><div class="box">Invoice — bill for goods sold on credit<br>Receipt — proof of payment received<br>Credit note — reduces a customer's debt (returns inwards)<br>Debit note — increases a customer's debt<br>Voucher — authorises a payment<br>Statement of account — periodic summary sent to a debtor</div><h4>Worked example</h4><p>Ada returns damaged goods worth ₦2,000 → you send her a CREDIT note for ₦2,000, reducing what she owes.</p><h4>Trap</h4><p>Credit note (seller reduces debt) vs debit note (seller increases debt) — the direction is the whole question.</p>` },
  { subject: 'Financial Accounting', title: 'Capital vs Revenue Expenditure', keywords: ['capital expenditure', 'revenue expenditure', 'expenditure', 'capitalised'],
    body: `<h4>The difference</h4><p><b>Capital expenditure</b> buys or improves a long-term asset — it goes on the balance sheet (machinery, vehicles, major upgrades).</p><p><b>Revenue expenditure</b> keeps the business running day to day — it is expensed in the profit and loss account (rent, fuel, repairs, wages).</p><h4>Worked example</h4><p>Buying a delivery van = capital. Fuel for the van = revenue. A NEW engine that extends the van's life = capital; routine servicing = revenue.</p><h4>Trap</h4><p>Treating revenue spending as capital OVERSTATES profit — WAEC loves this error question.</p>` },

  // ---------------- GOVERNMENT / CIVICS / GEOGRAPHY ----------------
  { subject: 'Government', title: 'Arms and Levels of Government', keywords: ['arms of government', 'legislature', 'executive', 'judiciary', 'levels of government', 'separation of powers', 'federal state local'],
    body: `<h4>The three arms</h4><div class="box">Legislature — MAKES laws (National Assembly: Senate + House of Reps)<br>Executive — IMPLEMENTS laws (President, ministers, civil service)<br>Judiciary — INTERPRETS laws and settles disputes (courts, headed by the Supreme Court)</div><p>Separation of powers with checks and balances stops any arm becoming tyrannical.</p><h4>Levels in Nigeria</h4><p>Federal → State → Local government (774 LGAs).</p><h4>Trap</h4><p>The President assenting to a bill is a CHECK by the executive on the legislature; courts can nullify unconstitutional laws — a check on both.</p>` },
  { subject: 'Government', title: 'The Constitution', keywords: ['constitution', 'supremacy of the constitution', 'fundamental human rights', 'constitution types'],
    body: `<h4>What it is</h4><p>The constitution is the supreme body of rules by which a state is governed — every law and official act must agree with it, or it is void.</p><h4>Types</h4><div class="box">Written — collected in one document (Nigeria, USA)<br>Unwritten — based on conventions and statutes (Britain)<br>Rigid — hard to amend (Nigeria: two-thirds majorities)<br>Flexible — amended like ordinary law</div><h4>Chapter IV rights</h4><p>Life, dignity, liberty, fair hearing, privacy, expression, assembly, movement — with lawful exceptions.</p><h4>Trap</h4><p>Nigeria's constitution is written AND rigid — say both when asked.</p>` },
  { subject: 'Civic Education', title: 'Values, Citizenship and Human Rights', keywords: ['civic education', 'citizenship', 'values', 'human rights', 'civic responsibility', 'dignity of labour', 'rule of law'],
    body: `<h4>Citizenship</h4><p>By birth, registration (marriage/descent) or naturalisation. Citizens owe loyalty, obedience to law, tax payment and defence of the nation — and receive protection, voting rights and welfare in return.</p><h4>Core values</h4><p>Honesty, integrity, dignity of labour, contentment, discipline, patriotism — the behaviours civic education drills.</p><h4>Rule of law</h4><p>Supremacy of law, equality before the law, and protection of fundamental rights — nobody is above the law, not even officials.</p><h4>Trap</h4><p>Rights come WITH duties: freedom of speech does not include slander; assembly does not include rioting.</p>` },
  { subject: 'Geography', title: 'Latitude and Longitude', keywords: ['latitude', 'longitude', 'equator', 'greenwich', 'great circle', 'time zones', 'map coordinates'],
    body: `<h4>The grid</h4><div class="box">Latitude — parallels EAST-WEST, measured from the Equator (0°) to poles (90°). Determines climate.<br>Longitude — meridians NORTH-SOUTH from Greenwich (0°) to 180°. Determines TIME.</div><h4>Time calculation</h4><p>Earth turns 360° in 24 hours → 15° = 1 hour → 1° = 4 minutes. East of Greenwich = ahead; west = behind.</p><h4>Worked example</h4><p>When it is 12 noon at Greenwich, time at 30°E = 12:00 + 2h = <b>2:00 pm</b>.</p><h4>Trap</h4><p>Nigeria sits roughly 4°–14°N and 3°–15°E — north of the Equator, just east of Greenwich (GMT+1).</p>` },
  { subject: 'Geography', title: "Earth's Movements and Their Effects", keywords: ['rotation', 'revolution', 'earth movements', 'day and night', 'seasons', 'eclipse'],
    body: `<h4>Rotation</h4><p>Spinning on its axis west→east every ~24 hours: causes day and night, time differences, and the deflection of winds (Coriolis).</p><h4>Revolution</h4><p>Orbiting the Sun in ~3651/4  days with a tilted axis (661/2 ° to the orbit): causes the SEASONS, varying day lengths, and the tropics/circles.</p><h4>Eclipses</h4><p>Solar — Moon between Sun and Earth (new moon). Lunar — Earth's shadow falls on the Moon (full moon).</p><h4>Trap</h4><p>Seasons come from the TILT, not from distance to the Sun — the classic trap.</p>` },
  { subject: 'Geography', title: 'Population', keywords: ['population', 'census', 'birth rate', 'death rate', 'population structure', 'overpopulation', 'migration'],
    body: `<h4>The vital statistics</h4><div class="box">Birth rate = live births per 1,000 people per year<br>Death rate = deaths per 1,000 per year<br>Natural growth = birth rate − death rate<br>Population density = total people ÷ land area</div><h4>Factors of growth</h4><p>Births, deaths and migration. Developing countries grow fast: high births, falling deaths (better medicine).</p><h4>Problems of overpopulation</h4><p>Pressure on schools/hospitals, unemployment, housing shortage, environmental strain.</p><h4>Trap</h4><p>Census problems in Nigeria: politics, funding, religion/ethnicity disputes and poor maps — always cite these in "why censuses fail" questions.</p>` },
  { subject: 'Agricultural Science', title: 'Soil — Types and Fertility', keywords: ['soil', 'sandy soil', 'clay soil', 'loam', 'soil fertility', 'manure', 'fertilizer', 'soil conservation'],
    body: `<h4>The three types</h4><div class="box">Sandy — large particles, drains fast, poor in nutrients<br>Clay — tiny particles, holds water, hard to work<br>Loam — the balanced mix, best for farming</div><h4>Fertility boosters</h4><p>Manure, compost, crop rotation (legumes fix nitrogen), cover cropping, bush fallowing, inorganic fertilisers (NPK).</p><h4>Conservation</h4><p>Contour ploughing, terracing, mulching, windbreaks — against erosion.</p><h4>Trap</h4><p>Leguminous crops (beans, groundnut) restore nitrogen through root-nodule bacteria — that is why they star rotation cycles.</p>` },
  { subject: 'Agricultural Science', title: 'Crop Production Practices', keywords: ['crop production', 'husbandry', 'planting', 'weeding', 'harvesting', 'crop rotation', 'agricultural practices'],
    body: `<h4>The cycle</h4><p>Land preparation → planting (spacing/depth per crop) → care (weeding, fertilizer, pest control, irrigation) → harvesting → processing → storage.</p><h4>Pest and disease control</h4><div class="box">Cultural — crop rotation, early planting, resistant varieties<br>Biological — natural enemies (ladybirds eat aphids)<br>Chemical — insecticides, fungicides, herbicides (use with care)</div><h4>Worked example</h4><p>Maize: plant 75 × 25 cm, two seeds per hole, thin to one; weed early — the first six weeks decide the yield.</p><h4>Trap</h4><p>Integrated pest management combines methods — exams reward "cultural FIRST, chemicals last".</p>` },
  { subject: 'Agricultural Science', title: 'Animal Husbandry', keywords: ['animal husbandry', 'livestock', 'poultry', 'cattle', 'animal diseases', 'ranching', 'animal nutrition'],
    body: `<h4>Management systems</h4><div class="box">Intensive — housed, fed, high input/output (battery poultry)<br>Semi-intensive — partial housing and grazing<br>Extensive — free range, low input (traditional herding)</div><h4>Classes of livestock</h4><p>Ruminants (cattle, sheep, goats — four-chambered stomach) vs non-ruminants/monogastrics (pigs, poultry).</p><h4>Common diseases</h4><p>Newcastle (poultry, viral), mastitis (udder infection in dairy), trypanosomiasis (sleeping sickness via tsetse fly).</p><h4>Trap</h4><p>Ruminants digest cellulose via microbial fermentation in the rumen — they can thrive on grass; poultry cannot.</p>` },
  { subject: 'Computer Studies', title: 'Hardware and Software', keywords: ['hardware', 'software', 'cpu', 'input output', 'system software', 'application software', 'computer components'],
    body: `<h4>Hardware = physical parts</h4><div class="box">Input — keyboard, mouse, scanner<br>CPU — control unit + ALU + registers ("the brain")<br>Output — monitor, printer, speaker<br>Storage — RAM (volatile, working memory) vs ROM/disk (permanent)</div><h4>Software = programs</h4><p>System software (operating systems like Windows, Android) manages the machine; application software (Word, a quiz app like StudyOS) does user tasks.</p><h4>Trap</h4><p>RAM loses everything when power goes — that is why you SAVE your work to disk. The CPU never stores permanently.</p>` },
  { subject: 'Computer Studies', title: 'The Internet and Digital Safety', keywords: ['internet', 'internet safety', 'cyber', 'email', 'browser', 'phishing', 'online safety', 'social media safety'],
    body: `<h4>Key terms</h4><p>Internet = the global network of networks. A browser displays web pages; a search engine finds them; email sends messages.</p><h4>Stay safe online</h4><div class="box">Strong, unique passwords + never share them<br>Never send money or personal data to strangers<br>Beware phishing — fake links pretending to be banks or MTN prizes<br>Think before you post — the internet never forgets</div><h4>Netiquette</h4><p>Be respectful, do not cyberbully, cite sources, and avoid plagiarism.</p><h4>Trap</h4><p>A legitimate bank will NEVER ask for your PIN or OTP by SMS/WhatsApp — instant scam signal.</p>` },
  { subject: 'Computer Studies', title: 'Data Processing and Number Systems', keywords: ['data processing', 'data information', 'binary', 'computer number system', 'ict cycle'],
    body: `<h4>The cycle</h4><div class="box">Data (raw facts) → input → processing → output → Information (meaningful data) → storage</div><h4>Number systems</h4><div class="box">Binary (base 2), octal (8), decimal (10), hexadecimal (16 — uses A–F for 10–15)</div><h4>Worked example</h4><p>1011(two) to decimal = 8 + 0 + 2 + 1 = <b>11</b>. Decimal 25 to binary = 11001.</p><h4>Trap</h4><p>Computers use binary because circuits have two states: ON (1) and OFF (0) — everything else is built from that.</p>` },
  { subject: 'Christian Religious Studies', title: 'Key CRS Themes', keywords: ['crs', 'christian religious', 'bible themes', 'ten commandments', 'sermon on the mount', 'faith and obedience'],
    body: `<h4>Recurring exam themes</h4><p>Faith and obedience (Abraham, Noah), courage (Daniel, Esther), repentance and forgiveness (the Prodigal Son), love and service (the Good Samaritan), humility vs pride.</p><h4>The Ten Commandments</h4><p>Duties to God (no other gods, no idols, do not misuse His name, keep the Sabbath) and to people (honour parents; no murder, adultery, stealing, false witness, coveting).</p><h4>Answering CRS questions</h4><p>Cite the passage or story → state what happened → the lesson for today's Nigerian society.</p><h4>Trap</h4><p>Always connect the story to a MORAL LESSON and a modern application — narrative alone earns half marks.</p>` },
  { subject: 'Islamic Religious Studies', title: 'Key IRS Themes', keywords: ['irs', 'islamic religious', 'five pillars', 'pillar of islam', 'quran themes', 'prophet muhammad lessons'],
    body: `<h4>The Five Pillars</h4><div class="box">Shahada — declaration of faith · Salat — five daily prayers<br>Zakat — almsgiving · Sawm — fasting in Ramadan · Hajj — pilgrimage to Makkah</div><h4>Recurring exam themes</h4><p>Honesty (the Prophet was Al-Amin, the trustworthy), patience (Sabr), respect for parents, knowledge-seeking, justice and community responsibility.</p><h4>Answering IRS questions</h4><p>State the teaching → reference its source (Qur'an/Hadith where asked) → apply it to daily life in Nigeria.</p><h4>Trap</h4><p>Zakat is OBLIGATORY charity on qualifying wealth (about 2.5%), distinct from voluntary sadaqah.</p>` },

  // ---------------- STUDY SKILLS (Buddy as coach) ----------------
  { subject: 'Study Skills', title: 'How to Memorise Formulas', keywords: ['memorise', 'memorize', 'remember formulas', 'memorize formulas', 'forget formulas', 'memory tips'],
    body: `<h4>What actually works</h4><p><b>1. Use them daily</b> — do 3 problems with each formula instead of staring at it. <b>2. Group by family</b> (all circle formulas together). <b>3. Mnemonics</b> — SOH CAH TOA, "My Dear Aunt Sally" for BODMAS. <b>4. Teach it</b> — explaining a formula to a friend locks it in. <b>5. Flashcards</b> — formula on front, worked example on back; run them in StudyOS every day.</p><h4>The science</h4><p>Spaced repetition beats cramming: review on day 1, day 3, day 7, day 21.</p><p><b>Try this now:</b> pick your three weakest formulas and drill each with one quiz question in the Practice Exam page. 🔥</p>` },
  { subject: 'Study Skills', title: 'How to Build a Study Timetable', keywords: ['timetable', 'study plan', 'schedule', 'how to plan my study', 'revision plan', 'reading plan'],
    body: `<h4>The 5-step build</h4><p><b>1.</b> List every subject and rank it by weakness. <b>2.</b> Give your WEAKEST subjects your BEST hours (not midnight leftovers). <b>3.</b> Work in focused blocks — 40 minutes on, 10 minutes off. <b>4.</b> Mix subjects daily (Maths + English + one science) so your brain never bores. <b>5.</b> End every week with one full mock to test the plan.</p><h4>Sample weekday</h4><div class="box">5–6 am: hardest subject (fresh brain)<br>After school: 2 × 40-min blocks<br>Evening: flashcards + today's quiz<br>Weekend: one full exam simulation</div><p>Your StudyOS daily mission already does step 1–4 for you — check it every morning. 📋</p>` },
  { subject: 'Study Skills', title: 'How to Stay Focused While Reading', keywords: ['focus', 'concentration', 'distracted', 'concentrate', 'stay focused', 'phone distraction'],
    body: `<h4>The focus recipe</h4><p><b>1. Phone jail:</b> put your phone in another room — not face-down, ANOTHER room. <b>2. One subject, one desk, one goal</b> ("finish 10 maths questions", not "read maths"). <b>3. Pomodoro:</b> 40 minutes hard, 10 minutes break — real breaks, not TikTok. <b>4. Active reading:</b> pen in hand — underline, question, summarise each page in one line. <b>5. Water and sleep:</b> a tired, thirsty brain cannot focus, full stop.</p><p><b>Buddy's challenge:</b> use the Focus timer in StudyOS for one 40-minute session today and keep your streak alive. 🔥</p>` },
  { subject: 'Study Skills', title: 'Beating Exam Fear', keywords: ['exam fear', 'exam anxiety', 'nervous', 'scared of exam', 'fear of failure', 'stage fright', 'afraid of jamb'],
    body: `<h4>First — normalise it</h4><p>Even the brightest students feel it. Fear is your body preparing to perform; the goal is to channel it, not delete it.</p><h4>The cure is preparation + routine</h4><p><b>1.</b> Simulate the exam BEFORE the exam — sit timed mocks in StudyOS so the real hall feels familiar. <b>2.</b> Know your weak topics and attack them early — uncertainty feeds fear. <b>3.</b> The night before: light review, pack your materials, sleep. <b>4.</b> In the hall: breathe slowly, do the questions you KNOW first, bank those marks, then return to the hard ones.</p><p>Every mock you finish here makes the real thing smaller. You've got this. 💪</p>` },
  { subject: 'Study Skills', title: 'The Night Before an Exam', keywords: ['night before exam', 'exam eve', 'cramming', 'what to do before exam', 'last minute revision'],
    body: `<h4>Do this</h4><p><b>1.</b> Review summaries and formula sheets — NOT new topics. <b>2.</b> Redo two or three past questions per weak topic. <b>3.</b> Pack everything: pens, pencil, ruler, calculator (if allowed), ID, exam slip. <b>4.</b> Sleep at least 7 hours — memory consolidation happens in sleep; all-nighters destroy recall.</p><h4>Never do this</h4><p>Learn brand-new chapters at 11 pm, argue answers with friends who panic you, or skip dinner.</p><h4>Morning of</h4><p>Light breakfast, arrive early, breathe. You prepared — now go collect your marks. 🎯</p>` },
  { subject: 'Study Skills', title: 'How to Pass JAMB/WAEC/NECO', keywords: ['pass jamb', 'pass waec', 'pass neco', 'exam success', 'how to score high', 'exam strategy', 'distinction'],
    body: `<h4>The proven system</h4><p><b>1. Syllabus first:</b> exams only test what the syllabus lists — and your topics here are aligned to it. <b>2. Past questions:</b> patterns repeat; do every past paper you can and study WHY each answer is right. <b>3. Weak-topic loop:</b> after every mock, redo only what you missed — your Progress page shows exactly where. <b>4. Time yourself:</b> knowing the content is half the battle; finishing in time is the other half. <b>5. Consistency:</b> 90 focused minutes daily beats 8 panicked hours on Sunday.</p><div class="box">Daily: 1 topic + 1 quiz · Weekly: 1 full mock · After each mock: fix the misses</div><p>Students who run this loop for 8–12 weeks transform their scores. Start today. 🚀</p>` },
  { subject: 'Study Skills', title: 'How to Take Notes That Work', keywords: ['note taking', 'notes', 'summarise', 'summary', 'how to take notes'],
    body: `<h4>The method</h4><p><b>1. Read first, write second</b> — never copy what you have not understood. <b>2. One page per topic</b> with a big title and 3–7 bullet points in YOUR words. <b>3. Boxes for formulas and definitions</b> — your eye should find them in one second. <b>4. Colours with a system</b> (e.g. red = traps, green = formulas). <b>5. The last line of every page: "Exam trap:"</b> — write the mistake people make.</p><h4>Why it works</h4><p>Writing in your own words forces understanding, and your one-pagers become perfect night-before-exam revision.</p>` },
  { subject: 'Study Skills', title: 'Studying With Friends (Group Study)', keywords: ['group study', 'study group', 'study with friends', 'reading group'],
    body: `<h4>Make groups work</h4><p><b>1. Small:</b> 3–4 people max. <b>2. Roles rotate:</b> one person teaches the topic, others question them — teaching exposes gaps. <b>3. Time-box it:</b> 90 minutes with an agenda ("today: quadratic equations + 10 past questions"). <b>4. Quiz each other</b> — no notes allowed. <b>5. End with action:</b> everyone leaves knowing what to fix before next meeting.</p><h4>When groups fail</h4><p>Too many people, no agenda, gossip sessions, and "we'll start in 10 minutes" that becomes 2 hours. Keep it tight or study alone.</p>` },

  // ---------------- STUDYOS APP HELP ----------------
  { subject: 'StudyOS Help', title: 'How to Sit a Mock Exam', keywords: ['mock exam', 'sit exam', 'practice exam', 'take exam', 'how to write exam', 'exam simulation', 'start exam'],
    body: `<h4>It takes 4 taps</h4><p><b>1.</b> Open <b>Practice Exam</b> from the menu. <b>2.</b> Tap your exam — BECE if you are in JSS, or JAMB / WAEC / NECO / NABTEB for senior classes. <b>3.</b> Choose your mode, how many questions per subject, and the time (or leave "Real exam" for the exact official settings). <b>4.</b> Hit Start.</p><h4>After the paper</h4><p>You get your score, per-subject performance, and every mistake explained — then one tap turns your weakest subject into tomorrow's mission.</p><p><b>Pro move:</b> sit one full mock every weekend under real timing. That is how exam halls stop being scary. 🎯</p>` },
  { subject: 'StudyOS Help', title: 'How to Use Quizzes and the Topic Page', keywords: ['how to quiz', 'topic quiz', 'take quiz', 'test yourself', 'how to study a topic'],
    body: `<h4>The daily loop</h4><p><b>1. Study:</b> open a topic from your subject and read the lesson — every topic has textbook-depth notes with examples. <b>2. Test:</b> tap <b>Test yourself</b> on the topic page for a quiz on exactly that topic. <b>3. Mix it up:</b> use the quiz page for mixed questions across the subject. <b>4. Review:</b> after every quiz, read the explanations for what you missed — that is where the marks are recovered.</p><p>Free quizzes are short tastes — the Bundle unlocks full-length papers and everything else. 📚</p>` },
  { subject: 'StudyOS Help', title: 'Understanding Your Progress Heatmap', keywords: ['heatmap', 'calendar', 'activity calendar', 'study calendar', 'consistency chart'],
    body: `<h4>What the squares mean</h4><p>Each square is one day. The deeper the colour, the more you studied that day — quizzes, lessons, flashcards and focus sessions all count. Grey = nothing logged.</p><h4>Why it matters</h4><p>Exams are won by chains of small days. Your goal: never let a long grey gap appear. One quiz a day keeps a square alive and your streak burning. 🔥</p><p><b>Read it like a coach:</b> dark clusters = good weeks; find what you did differently and repeat it.</p>` },
  { subject: 'StudyOS Help', title: 'Streaks and Streak Freezes', keywords: ['streak', 'streak freeze', 'daily streak', 'keep streak', 'freeze'],
    body: `<h4>How streaks work</h4><p>A day counts when you complete at least one real study activity — a lesson, a quiz, some flashcards or a focus session. The counter climbs; miss a day and it restarts at 1.</p><h4>Streak freezes ❄️</h4><p>Every 7-day milestone banks a freeze (up to 3). If you miss a day while holding a freeze, the freeze is spent automatically and your streak survives.</p><h4>Pro move</h4><p>Keep at least one freeze in the bank during exam season — life happens, and your streak deserves a safety net. 🔥</p>` },
  { subject: 'StudyOS Help', title: 'Changing Your Class or Subjects', keywords: ['change class', 'change subject', 'switch subject', 'wrong class', 'select subjects', 'choose subject'],
    body: `<h4>Easy fix</h4><p>Open your <b>Profile</b> page — your class (JSS1–SS3) and subjects are listed there and can be updated. Your topics, quizzes and exam sets instantly re-align to your class.</p><h4>How the app protects you</h4><p>StudyOS never shows content above your stage: JSS students see junior content and BECE exams; SS students see senior content and JAMB/WAEC/NECO/NABTEB.</p><p><b>Tip:</b> pick exactly the subjects your school offers — your daily mission and mocks will match your real timetable.</p>` },
  { subject: 'StudyOS Help', title: 'Flashcards and Spaced Repetition', keywords: ['flashcards', 'flash card', 'spaced repetition', 'memory cards', 'got it later'],
    body: `<h4>How to use them well</h4><p>Flip a card and grade yourself honestly: <b>Got it!</b> or <b>Get it next time</b>. Cards you miss come back in a retry deck — that repetition is the whole point.</p><h4>The routine that works</h4><div class="box">Morning: 10 cards with breakfast<br>After school: your weakest subject's deck<br>Night: the retry deck until empty</div><p>Flashcards are for definitions, formulas and terms — the things exams ask verbatim. Five minutes daily beats an hour before the exam.</p>` },
  { subject: 'StudyOS Help', title: 'The Bundle — What You Get', keywords: ['bundle', 'what do i get', 'upgrade', 'premium', 'pro features', 'is it worth it', 'pay for studyos'],
    body: `<h4>One payment. Everything. Forever.</h4><p>The StudyOS Bundle is a single one-time payment — no subscription, no renewal. It unlocks:</p><ul><li>Unlimited full-length quizzes on every topic</li><li>Full lesson notes and flashcards across all 13 subjects</li><li>Buddy — ask anything, as often as you like</li><li>The complete BECE / WAEC / JAMB / NECO exam engine with scoring and predictions</li><li>Every future update, free</li></ul><p>To activate: tap <b>Activate</b>, follow Buddy's payment steps, and enter the key you receive. That's it — the whole school is yours. 🎓</p>` }
];
